// 기능: 구문 강조, 실시간 오류 표시, 자동완성, 포맷팅

const String editorHTML = r'''
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>FreeLang IDE</title>

  <!-- CodeMirror 6 CSS -->
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/codemirror6/0.20.0/codemirror.min.css">
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: 'Monaco', 'Menlo', monospace;
      background: #1e1e1e;
      color: #d4d4d4;
      height: 100vh;
      display: flex;
      flex-direction: column;
      overflow: hidden;
    }

    #editor-container {
      flex: 1;
      overflow: hidden;
      position: relative;
    }

    .cm-editor {
      height: 100%;
      font-size: 13px;
      line-height: 1.6;
    }

    /* FreeLang 구문 강조 */
    .cm-variable { color: #9cdcfe; }
    .cm-keyword { color: #569cd6; font-weight: bold; }
    .cm-string { color: #ce9178; }
    .cm-number { color: #b5cea8; }
    .cm-comment { color: #6a9955; }
    .cm-function { color: #dcdcaa; }
    .cm-operator { color: #d4d4d4; }
    .cm-bracket { color: #d4d4d4; }

    /* 오류 표시 */
    .cm-diagnostic-error {
      background-color: rgba(244, 67, 54, 0.2);
      border-left: 3px solid #f44336;
      padding-left: 8px;
    }

    .cm-line {
      padding-left: 12px;
    }

    /* 라인 번호 */
    .cm-gutters {
      background: #252526;
      border-right: 1px solid #333;
    }

    .cm-linenumber {
      color: #858585;
      padding-right: 12px;
    }

    /* 자동완성 팝업 */
    .cm-completionPopup {
      background: #2d2d30;
      border: 1px solid #464647;
      border-radius: 4px;
      max-height: 200px;
      overflow-y: auto;
      padding: 4px 0;
    }

    .cm-completionOption {
      padding: 6px 12px;
      color: #d4d4d4;
      cursor: pointer;
    }

    .cm-completionOption.selected {
      background: #0e639c;
    }

    #info-panel {
      height: auto;
      background: #252526;
      border-top: 1px solid #333;
      padding: 8px 12px;
      font-size: 11px;
      color: #d4d4d4;
      max-height: 80px;
      overflow-y: auto;
    }

    .error-line {
      color: #f48771;
    }

    .warning-line {
      color: #cca700;
    }
  </style>
</head>
<body>
  <div id="editor-container"></div>
  <div id="info-panel"></div>

  <!-- CodeMirror 6 JS -->
  <script src="https://cdnjs.cloudflare.com/ajax/libs/codemirror6/0.20.0/codemirror.min.js"></script>
  <script>
    // ==================== FreeLang Tokenizer ====================

    class FreeLangTokenizer {
      constructor() {
        this.keywords = new Set([
          'let', 'fn', 'if', 'else', 'match', 'while', 'for', 'return',
          'break', 'continue', 'true', 'false', 'nil', 'import', 'module',
          'record', 'variant', 'type', 'impl', 'pub', 'mut', 'ref',
        ]);

        this.builtins = new Set([
          'print', 'println', 'input', 'len', 'push', 'pop', 'reverse',
          'map', 'filter', 'fold', 'range', 'zip', 'unzip', 'assert',
        ]);
      }

      tokenize(code) {
        const tokens = [];
        const lines = code.split('\n');
        let pos = 0;

        for (let line of lines) {
          let col = 0;

          // 주석 처리
          const commentIdx = line.indexOf('//');
          if (commentIdx >= 0) {
            if (commentIdx > 0) {
              this._tokenizeLine(line.substring(0, commentIdx), tokens, pos, 0);
            }
            tokens.push({
              type: 'comment',
              start: pos + commentIdx,
              length: line.length - commentIdx,
              line: pos / (code.length / lines.length),
            });
            pos += line.length + 1;
            continue;
          }

          this._tokenizeLine(line, tokens, pos, 0);
          pos += line.length + 1;
        }

        return tokens;
      }

      _tokenizeLine(line, tokens, lineStart, lineNum) {
        let i = 0;
        while (i < line.length) {
          const ch = line[i];

          // 공백
          if (/\s/.test(ch)) {
            i++;
            continue;
          }

          // 문자열
          if (ch === '"') {
            const end = line.indexOf('"', i + 1);
