class SampleGames {
  static String get simpleGame => '''
// SimpleGame.flg - 터치로 플레이어 이동
scene MainGame {
  sprite Player {
    x = 160, y = 300,
    w = 32, h = 32,
    speed = 5.0,
    on touch(x, y) { move_to(x, y) }
  }

  sprite Goal {
    x = 160, y = 100,
    w = 48, h = 48,
    on collision() { scene_change("Win") }
  }
}

scene Win {
  sprite Text {
    x = 100, y = 300,
    w = 160, h = 50
  }
  on touch(x, y) { scene_change("MainGame") }
}
''';

  static String get bounceGame => '''
// BounceGame.flg - 공 튀기기 게임
scene Play {
  sprite Ball {
    x = 180, y = 320,
    w = 16, h = 16,
    speed = 8.0,
    on update(dt) {
      if x > 340 { rotate(360) }
    }
  }

  sprite Paddle {
    x = 120, y = 600,
    w = 120, h = 20,
    on touch(x, y) { move_to(x, y) }
  }
}
''';

  static String get runnerGame => '''
// RunnerGame.flg - 달리기 게임
scene Game {
  sprite Player {
    x = 160, y = 550,
    w = 32, h = 32,
    on touch(x, y) { rotate(45) }
    on update(dt) {
      if y < 100 { scene_change("GameOver") }
    }
  }
}

scene GameOver {
  on touch(x, y) { scene_change("Game") }
}
''';
}

