// dsl_editor_screen.dart - FreeLang Game DSL 에디터

import 'package:flutter/material.dart';
import 'package:flame/game.dart';
import '../dsl/game_parser.dart';
import '../services/flame_game_runtime.dart';
import 'game_selector_screen.dart';

class DSLEditorScreen extends StatefulWidget {
  const DSLEditorScreen({Key? key}) : super(key: key);

  @override
  State<DSLEditorScreen> createState() => _DSLEditorScreenState();
}

class _DSLEditorScreenState extends State<DSLEditorScreen> {
  late TextEditingController _controller;
  List<String> _errors = [];
  bool _isValidDSL = true;

  @override
  void initState() {
    super.initState();
    _controller = TextEditingController(
      text: '''scene MainGame {
  sprite Player {
    x = 160, y = 300,
    w = 32, h = 32,
    on touch(x, y) { move_to(x, y) }
  }
}
''',
    );
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void _validateDSL() {
    _errors.clear();
    try {
      final parser = GameDSLParser();
      parser.parse(_controller.text);
      setState(() => _isValidDSL = true);
    } on ParseException catch (e) {
      setState(() {
        _isValidDSL = false;
        _errors = [e.toString()];
      });
    } catch (e) {
      setState(() {
        _isValidDSL = false;
        _errors = ['오류: $e'];
      });
    }
  }

  Future<void> _runGame() async {
    _validateDSL();

    if (!_isValidDSL) {
      _showError('DSL에 오류가 있습니다');
      return;
    }

    try {
      final parser = GameDSLParser();
      final gameDef = parser.parse(_controller.text);
      final gameRuntime = FreeLangGameRuntime(gameDefinition: gameDef);

      if (!mounted) return;

      Navigator.push(
        context,
        MaterialPageRoute(
          builder: (context) => GamePlayScreen(game: gameRuntime),
        ),
      );
    } catch (e) {
      _showError('게임 실행 실패: $e');
    }
  }

  void _showError(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(message),
        backgroundColor: Colors.red,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        // 에디터
        Expanded(
          flex: 2,
          child: Container(
            margin: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: Colors.grey[900],
              border: Border.all(color: Colors.grey[700]!),
              borderRadius: BorderRadius.circular(8),
            ),
            child: TextField(
              controller: _controller,
              style: const TextStyle(
                fontFamily: 'Monaco',
                fontSize: 12,
                color: Color(0xFFD4D4D4),
              ),
              decoration: const InputDecoration(
                border: InputBorder.none,
                contentPadding: EdgeInsets.all(12),
                hintText: '게임 DSL을 입력하세요...',
                hintStyle: TextStyle(color: Color(0xFF666666)),
              ),
              maxLines: null,
              expands: true,
              onChanged: (_) {
                _validateDSL();
              },
            ),
          ),
        ),

        // 오류 표시
        if (!_isValidDSL && _errors.isNotEmpty)
          Container(
            margin: const EdgeInsets.symmetric(horizontal: 12),
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: Colors.red[900],
              borderRadius: BorderRadius.circular(8),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  'DSL 오류:',
                  style: TextStyle(
                    fontWeight: FontWeight.bold,
                    color: Colors.white,
                  ),
                ),
                ..._errors
                    .map((error) => Text(
                          error,
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 11,
                          ),
                        ))
                    .toList(),
              ],
            ),
          ),

        // 컨트롤 버튼
        Container(
          padding: const EdgeInsets.all(12),
          child: Row(
            children: [
              Expanded(
                child: ElevatedButton.icon(
                  onPressed: _isValidDSL ? _runGame : null,
                  icon: const Icon(Icons.play_arrow),
                  label: const Text('실행'),
                ),
              ),
              const SizedBox(width: 8),
              ElevatedButton.icon(
                onPressed: _validateDSL,
                icon: const Icon(Icons.check),
                label: const Text('검증'),
              ),
              const SizedBox(width: 8),
              ElevatedButton.icon(
                onPressed: () {
                  _controller.text = _getSampleDSL();
                },
                icon: const Icon(Icons.content_copy),
                label: const Text('샘플'),
              ),
            ],
          ),
        ),
      ],
    );
  }

  String _getSampleDSL() => '''scene MainGame {
  sprite Player {
    x = 160, y = 300,
    w = 32, h = 32,
    speed = 5.0,
    on touch(x, y) { move_to(x, y) }
  }

  sprite Enemy {
    x = 160, y = 100,
    w = 48, h = 48,
    on update(dt) {
      if x > 300 { scene_change("Win") }
    }
  }
}

scene Win {
  on touch(x, y) { scene_change("MainGame") }
}
''';
}

