     1→// fl-engine: FreeLang Mobile 실행 엔진 FFI
     2→// Rust로 작성된 freelang-vm을 C 바인딩으로 노출합니다.
     3→// Android: JNI 브릿지가 이 함수들을 호출
     4→// iOS: Swift 브릿지가 이 함수들을 호출
     5→
     6→use std::ffi::{CStr, CString};
     7→use std::os::raw::{c_char, c_int};
     8→use std::ptr;
     9→use std::sync::Mutex;
    10→
    11→// ============================================================================
    12→// 데이터 구조
    13→// ============================================================================
    14→
    15→/// 실행 결과 구조체
    16→#[repr(C)]
    17→pub struct FlResult {
    18→    pub success: c_int,           // 1 = 성공, 0 = 실패
    19→    pub output: *mut c_char,      // 표준 출력 (C가 free 해야 함)
    20→    pub error: *mut c_char,       // 오류 메시지
    21→    pub time_ms: u32,             // 실행 시간
    22→    pub exit_code: c_int,         // 종료 코드
    23→}
    24→
    25→/// 토큰 구조체 (구문 강조용)
    26→#[repr(C)]
    27→pub struct FlToken {
    28→    pub token_type: c_int,        // 0=keyword, 1=identifier, 2=number 등
    29→    pub start: c_int,             // 시작 위치
    30→    pub length: c_int,            // 길이
    31→}
    32→
    33→/// 오류 구조체 (LSP용)
    34→#[repr(C)]
    35→pub struct FlError {
    36→    pub line: c_int,
    37→    pub col: c_int,
    38→    pub message: *mut c_char,
    39→    pub severity: c_int,          // 0=error, 1=warning, 2=info
    40→}
    41→
    42→/// LSP 자동완성 아이템
    43→#[repr(C)]
    44→pub struct FlCompletion {
    45→    pub label: *mut c_char,
    46→    pub kind: c_int,              // 1=keyword, 2=function, 3=variable 등
    47→    pub detail: *mut c_char,
    48→}
    49→
    50→// ============================================================================
    51→// 엔진 인스턴스 (전역 상태 관리)
    52→// ============================================================================
    53→
    54→lazy_static::lazy_static! {
    55→    static ref ENGINE_STATE: Mutex<Option<String>> = Mutex::new(None);
    56→}
    57→
    58→// ============================================================================
    59→// Public API (C에서 호출 가능)
    60→// ============================================================================
    61→
    62→/// 엔진 초기화
    63→/// 반환: 항상 0 (성공)
    64→#[no_mangle]
    65→pub extern "C" fn fl_engine_init() -> c_int {
    66→    let mut state = ENGINE_STATE.lock().unwrap();
    67→    *state = Some(String::from("initialized"));
    68→    0
    69→}
    70→
    71→/// 엔진 정리
    72→#[no_mangle]
    73→pub extern "C" fn fl_engine_shutdown() {
    74→    let mut state = ENGINE_STATE.lock().unwrap();
    75→    *state = None;
    76→}
    77→
    78→/// 경로 A: 바이트코드 인터프리터로 실행 (iOS 안전)
    79→///
    80→/// # 인자
    81→/// - `source`: FreeLang 소스 코드 (null-terminated C string)
    82→/// - `timeout_ms`: 타임아웃 (밀리초, 0=무제한)
    83→///
    84→/// # 반환
    85→/// `FlResult` 구조체 (호출자가 `fl_result_free()` 호출 필수)
    86→#[no_mangle]
    87→pub extern "C" fn fl_run_bytecode(
    88→    source: *const c_char,
    89→    timeout_ms: u32,
    90→) -> FlResult {
    91→    // 1. C 문자열 → Rust String 변환
    92→    let source_cstr = match unsafe { CStr::from_ptr(source) }.to_str() {
    93→        Ok(s) => s.to_string(),
    94→        Err(_) => {
    95→            return FlResult {
    96→                success: 0,
    97→                output: create_cstring(""),
    98→                error: create_cstring("Invalid UTF-8 in source code"),
    99→                time_ms: 0,
   100→                exit_code: 1,
   101→            }
   102→        }
   103→    };
   104→
   105→    // 2. 실제 구현: freelang-vm 호출
   106→    // TODO: freelang-vm crate를 import 후 다음과 같이 호출:
   107→    //
   108→    // let start = std::time::Instant::now();
   109→    // let result = freelang_vm::execute(&source_cstr, timeout_ms);
   110→    // let elapsed = start.elapsed().as_millis() as u32;
   111→
   112→    // 임시 구현 (테스트용)
   113→    let output = format!("Executed: {} chars\n", source_cstr.len());
   114→    let elapsed = 15; // ms
   115→
   116→    FlResult {
   117→        success: 1,
   118→        output: create_cstring(&output),
   119→        error: create_cstring(""),
   120→        time_ms: elapsed,
   121→        exit_code: 0,
   122→    }
   123→}
   124→
   125→/// 경로 B: C 코드 생성 후 네이티브 컴파일 (Android 성능)
   126→///
   127→/// 주의: iOS에서는 JIT 정책 위반으로 불가능
   128→#[no_mangle]
   129→pub extern "C" fn fl_run_native(
   130→    source: *const c_char,
   131→    timeout_ms: u32,
   132→) -> FlResult {
   133→    let source_cstr = match unsafe { CStr::from_ptr(source) }.to_str() {
   134→        Ok(s) => s.to_string(),
   135→        Err(_) => {
   136→            return FlResult {
   137→                success: 0,
   138→                output: create_cstring(""),
   139→                error: create_cstring("Invalid UTF-8 in source code"),
   140→                time_ms: 0,
   141→                exit_code: 1,
   142→            }
   143→        }
   144→    };
   145→
   146→    // 2. 실제 구현: freelang-to-c + TCC 컴파일
   147→    // TODO: freelang-to-c로 C 코드 생성 후 TCC/gcc로 컴파일
   148→
   149→    // 임시 구현
   150→    let output = format!("Native executed: {} chars\n", source_cstr.len());
   151→
   152→    FlResult {
   153→        success: 1,
   154→        output: create_cstring(&output),
   155→        error: create_cstring(""),
   156→        time_ms: 25,
   157→        exit_code: 0,
   158→    }
   159→}
   160→
   161→/// 구문 강조용 토큰화
   162→#[no_mangle]
   163→pub extern "C" fn fl_tokenize(
   164→    source: *const c_char,
   165→    out_count: *mut c_int,
   166→) -> *mut FlToken {
   167→    let source_cstr = match unsafe { CStr::from_ptr(source) }.to_str() {
   168→        Ok(s) => s,
   169→        Err(_) => {
   170→            unsafe { *out_count = 0 };
   171→            return ptr::null_mut();
   172→        }
   173→    };
   174→
   175→    // TODO: fv-lang-wasm 파서 사용
   176→    // 임시 구현: "let", "print" 등 키워드 감지
   177→
   178→    let mut tokens = Vec::new();
   179→    if source_cstr.contains("let") {
   180→        tokens.push(FlToken {
   181→            token_type: 0, // keyword
   182→            start: 0,
   183→            length: 3,
   184→        });
   185→    }
   186→
   187→    let count = tokens.len() as c_int;
   188→    unsafe { *out_count = count };
   189→
   190→    if tokens.is_empty() {
   191→        return ptr::null_mut();
   192→    }
   193→
   194→    let boxed = Box::leak(tokens.into_boxed_slice());
   195→    boxed.as_mut_ptr()
   196→}
   197→
   198→/// 실행 결과 메모리 해제
   199→#[no_mangle]
   200→pub extern "C" fn fl_result_free(result: *mut FlResult) {
   201→    if result.is_null() {
   202→        return;
   203→    }
   204→
   205→    unsafe {
   206→        let r = &*result;
   207→        if !r.output.is_null() {
   208→            let _ = CString::from_raw(r.output);
   209→        }
   210→        if !r.error.is_null() {
   211→            let _ = CString::from_raw(r.error);
   212→        }
   213→        let _ = Box::from_raw(result);
   214→    }
   215→}
   216→
   217→/// 토큰 배열 메모리 해제
   218→#[no_mangle]
   219→pub extern "C" fn fl_tokens_free(tokens: *mut FlToken, count: c_int) {
   220→    if tokens.is_null() || count <= 0 {
   221→        return;
   222→    }
   223→
   224→    unsafe {
   225→        let _ = Vec::from_raw_parts(tokens, count as usize, count as usize);
   226→    }
   227→}
   228→
   229→// ============================================================================
   230→// 유틸리티 함수
   231→// ============================================================================
   232→
   233→/// Rust String → C CString 변환 헬퍼
   234→fn create_cstring(s: &str) -> *mut c_char {
   235→    match CString::new(s) {
   236→        Ok(cstr) => cstr.into_raw(),
   237→        Err(_) => unsafe { CString::from_raw(ptr::null_mut()) }.into_raw(),
   238→    }
   239→}
   240→
   241→// ============================================================================
   242→// 테스트
   243→// ============================================================================
   244→
   245→#[cfg(test)]
   246→mod tests {
   247→    use super::*;
   248→
   249→    #[test]
   250→    fn test_engine_init() {
   251→        let result = unsafe { fl_engine_init() };
   252→        assert_eq!(result, 0);
   253→    }
   254→
   255→    #[test]
   256→    fn test_run_bytecode() {
   257→        let code = c"print 'hello'";
   258→        let result = unsafe { fl_run_bytecode(code.as_ptr(), 5000) };
   259→
   260→        assert_eq!(result.success, 1);
   261→        assert_eq!(result.exit_code, 0);
   262→
   263→        unsafe {
   264→            let _ = CString::from_raw(result.output);
   265→            let _ = CString::from_raw(result.error);
   266→        }
   267→    }
   268→}
