   327→  // ==================== 리더보드 API ====================
   328→
   329→  /// 리더보드 조회
   330→  /// [period]: 'weekly', 'monthly', 'alltime'
   331→  Future<List<LeaderboardEntryResponse>> getLeaderboard({
   332→    String period = 'weekly',
   333→  }) async {
   334→    try {
   335→      final response = await _dio.get<Map<String, dynamic>>(
   336→        '/leaderboard',
   337→        queryParameters: {'period': period},
   338→      );
   339→
   340→      final data = response.data?['data'] as List? ?? [];
   341→      return data
   342→          .map((item) => LeaderboardEntryResponse.fromJson(
   343→              item as Map<String, dynamic>))
   344→          .toList();
   345→    } on DioException catch (e) {
   346→      throw ApiException(
   347→        message: '리더보드 조회 실패',
   348→        statusCode: e.response?.statusCode,
   349→        originalError: e,
   350→      );
   351→    }
   352→  }
   353→
   354→  // ==================== 헬스체크 ====================
   355→
   356→  /// API 서버 상태 확인
   357→  Future<bool> healthCheck() async {
   358→    try {
   359→      final response = await _dio.get<Map<String, dynamic>>(
   360→        '/health',
   361→        options: Options(
   362→          receiveTimeout: const Duration(seconds: 3),
   363→        ),
   364→      );
   365→      return response.statusCode == 200;
   366→    } catch (e) {
   367→      return false;
   368→    }
   369→  }
   370→}
   371→
   372→// ==================== 인터셉터 ====================
   373→
   374→class LoggingInterceptor extends Interceptor {
   375→  @override
   376→  void onRequest(RequestOptions options, RequestInterceptorHandler handler) {
   377→    print('[API] ${options.method} ${options.path}');
   378→    handler.next(options);
   379→  }
   380→
   381→  @override
   382→  void onResponse(Response response, ResponseInterceptorHandler handler) {
   383→    print('[API] ✓ ${response.statusCode} ${response.requestOptions.path}');
   384→    handler.next(response);
   385→  }
   386→
   387→  @override
   388→  void onError(DioException err, ErrorInterceptorHandler handler) {
   389→    print('[API] ✗ ${err.response?.statusCode} - ${err.message}');
   390→    handler.next(err);
   391→  }
   392→}
   393→
   394→class ErrorInterceptor extends Interceptor {
   395→  @override
   396→  void onError(DioException err, ErrorInterceptorHandler handler) {
   397→    if (err.response?.statusCode == 401) {
   398→      // 미인증 - 로그인 재필요
   399→      print('[API] 인증 만료');
   400→    } else if (err.response?.statusCode == 429) {
   401→      // Rate limit
   402→      print('[API] 요청 제한 초과');
   403→    } else if (err.type == DioExceptionType.connectionTimeout ||
   404→        err.type == DioExceptionType.receiveTimeout) {
   405→      print('[API] 타임아웃');
   406→    }
   407→    handler.next(err);
   408→  }
   409→}
