package api

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"strconv"
	"time"
)

// ==================== 데이터 모델 ====================

type Notification struct {
	ID            string    `json:"id"`
	UserID        string    `json:"user_id"`
	Type          string    `json:"type"` // 'comment' | 'like'
	ActorUsername string    `json:"actor_username"`
	SnippetID     string    `json:"snippet_id"`
	SnippetTitle  string    `json:"snippet_title"`
	IsRead        bool      `json:"is_read"`
	CreatedAt     time.Time `json:"created_at"`
}

// ==================== 테이블 초기화 ====================

func InitNotificationsTable(db *sql.DB) error {
	schema := `
	CREATE TABLE IF NOT EXISTS notifications (
		id TEXT PRIMARY KEY,
		user_id TEXT NOT NULL,
		type TEXT NOT NULL,
		actor_username TEXT NOT NULL,
		snippet_id TEXT NOT NULL,
		snippet_title TEXT NOT NULL,
		is_read INTEGER DEFAULT 0,
		created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
		FOREIGN KEY (user_id) REFERENCES users(id),
		FOREIGN KEY (snippet_id) REFERENCES snippets(id) ON DELETE CASCADE
	);

	CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id, created_at DESC);
	`

	_, err := db.Exec(schema)
	return err
}

// ==================== HTTP 핸들러 ====================

// GET /api/v2/notifications
// JWT 필요, 내 알림 목록 (최신 30개)
func GetNotifications(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, ok := r.Context().Value("user_id").(string)
		if !ok {
			WriteError(w, http.StatusUnauthorized, "User not authenticated", 401)
			return
		}

		rows, err := db.Query(`
			SELECT id, user_id, type, actor_username, snippet_id, snippet_title, is_read, created_at
			FROM notifications
			WHERE user_id = ?
			ORDER BY created_at DESC
			LIMIT 30
		`, userID)

		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Database query failed", 500)
			return
		}
		defer rows.Close()

		notifications := []Notification{}
		for rows.Next() {
			var n Notification
			var isRead int
			if err := rows.Scan(&n.ID, &n.UserID, &n.Type, &n.ActorUsername, &n.SnippetID, &n.SnippetTitle, &isRead, &n.CreatedAt); err != nil {
				continue
			}
			n.IsRead = isRead == 1
			notifications = append(notifications, n)
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"data":    notifications,
			"count":   len(notifications),
		})
	}
}

// POST /api/v2/notifications/{id}/read
// JWT 필요, 알림을 읽음 처리
func MarkNotificationRead(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, ok := r.Context().Value("user_id").(string)
		if !ok {
			WriteError(w, http.StatusUnauthorized, "User not authenticated", 401)
			return
		}

		notificationID := r.PathValue("id")
		if notificationID == "" {
			WriteError(w, http.StatusBadRequest, "Notification ID required", 400)
			return
		}

		// 자신의 알림인지 확인
		var ownerID string
		err := db.QueryRow("SELECT user_id FROM notifications WHERE id = ?", notificationID).Scan(&ownerID)
		if err == sql.ErrNoRows {
			WriteError(w, http.StatusNotFound, "Notification not found", 404)
			return
		}
		if ownerID != userID {
			WriteError(w, http.StatusForbidden, "Not your notification", 403)
			return
		}

		_, err = db.Exec("UPDATE notifications SET is_read = 1 WHERE id = ?", notificationID)
		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Failed to update", 500)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
		})
	}
}

// POST /api/v2/notifications/read-all
// JWT 필요, 모든 알림을 읽음 처리
func MarkAllNotificationsRead(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, ok := r.Context().Value("user_id").(string)
		if !ok {
			WriteError(w, http.StatusUnauthorized, "User not authenticated", 401)
			return
		}

		_, err := db.Exec("UPDATE notifications SET is_read = 1 WHERE user_id = ?", userID)
		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Failed to update", 500)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
		})
	}
}

// GET /api/v2/notifications/count
// JWT 필요, 미읽은 알림 수
func GetUnreadNotificationCount(db *sql.DB) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		userID, ok := r.Context().Value("user_id").(string)
		if !ok {
			WriteError(w, http.StatusUnauthorized, "User not authenticated", 401)
			return
		}

		var count int
		err := db.QueryRow("SELECT COUNT(*) FROM notifications WHERE user_id = ? AND is_read = 0", userID).Scan(&count)
		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Database query failed", 500)
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"count":   count,
		})
	}
}

// ==================== 헬퍼 함수 ====================

// 알림 생성 (내부용)
func createNotification(db *sql.DB, userID, notificationType, actorUsername, snippetID, snippetTitle string) error {
	// 본인에게 알림 생성 안 함
	var snippetAuthor string
	err := db.QueryRow("SELECT author FROM snippets WHERE id = ?", snippetID).Scan(&snippetAuthor)
	if err != nil || snippetAuthor == actorUsername {
		return nil // 본인 스니펫이면 알림 생성 안 함
	}

	notificationID := generateID("notif")
	_, err = db.Exec(`
		INSERT INTO notifications (id, user_id, type, actor_username, snippet_id, snippet_title, created_at)
		VALUES (?, ?, ?, ?, ?, ?, ?)
	`, notificationID, userID, notificationType, actorUsername, snippetID, snippetTitle, time.Now().UTC())

	return err
}

