// pong.dart - Pong 게임 (난이도: 중)
// 양쪽 패들로 공을 주고받는 1인 게임

import '../dsl/game_ast.dart';

// ==================== Pong 게임 정의 ====================

Game createPongGame() {
  const screenWidth = 800.0;
  const screenHeight = 600.0;

  // 공
  final ball = Sprite(
    id: 'ball',
    position: Position(400, 300),
    size: Size(20, 20),
    backgroundColor: Color(r: 255, g: 255, b: 255), // 하양
    eventHandlers: [
      // 공 이동
      EventHandler(
        type: EventType.update,
        action: BallMoveAction(spriteId: 'ball', initialVx: 200, initialVy: 150),
      ),
      // 벽 충돌 (위/아래)
      EventHandler(
        type: EventType.update,
        action: BallBounceAction(spriteId: 'ball'),
      ),
    ],
  );

  // 패들 1 (좌측)
  final paddle1 = Sprite(
    id: 'paddle1',
    position: Position(30, 300),
    size: Size(20, 100),
    backgroundColor: Color(r: 0, g: 0, b: 255), // 파강
    eventHandlers: [
      // 마우스/터치로 이동
      EventHandler(
        type: EventType.update,
        action: PaddleFollowAction(
          spriteId: 'paddle1',
          targetY: 'mouse_y',
        ),
      ),
      // 공과 충돌
      EventHandler(
        type: EventType.update,
        action: PaddleCollisionAction(
          paddleId: 'paddle1',
          ballId: 'ball',
        ),
      ),
    ],
  );

  // 패들 2 (우측)
  final paddle2 = Sprite(
    id: 'paddle2',
    position: Position(770, 300),
    size: Size(20, 100),
    backgroundColor: Color(r: 255, g: 0, b: 0), // 빨강
    eventHandlers: [
      // AI 자동 이동
      EventHandler(
        type: EventType.update,
        action: PaddleAIAction(
          spriteId: 'paddle2',
          ballId: 'ball',
          difficulty: 0.8, // 0.0 (쉬움) ~ 1.0 (어려움)
        ),
      ),
      // 공과 충돌
      EventHandler(
        type: EventType.update,
        action: PaddleCollisionAction(
          paddleId: 'paddle2',
          ballId: 'ball',
        ),
      ),
    ],
  );

  // 점수 표시 (좌측)
  final score1Display = Sprite(
    id: 'score1_display',
    position: Position(100, 50),
    size: Size(100, 60),
    backgroundColor: Color(r: 0, g: 0, b: 200),
  );

  // 점수 표시 (우측)
  final score2Display = Sprite(
    id: 'score2_display',
    position: Position(700, 50),
    size: Size(100, 60),
    backgroundColor: Color(r: 200, g: 0, b: 0),
  );

  // 센터 라인
  final centerLine = Sprite(
    id: 'center_line',
    position: Position(400, 300),
    size: Size(4, 600),
    backgroundColor: Color(r: 200, g: 200, b: 200),
  );

  final scene = Scene(
    id: 'gameplay',
    title: 'Pong',
    sprites: {
      'ball': ball,
      'paddle1': paddle1,
      'paddle2': paddle2,
      'score1_display': score1Display,
      'score2_display': score2Display,
      'center_line': centerLine,
    },
    backgroundColor: Color(r: 0, g: 0, b: 0), // 검정
    globalEvents: [
      // 공 벗어남 감지 (점수 증가)
      EventHandler(
        type: EventType.update,
        action: BallOutOfBoundsAction(
          ballId: 'ball',
          screenWidth: screenWidth,
        ),
      ),
      // 최대 점수 달성 감지 (게임 오버)
      EventHandler(
        type: EventType.update,
        action: PongWinConditionAction(maxScore: 10),
      ),
    ],
  );

  return Game(
    id: 'pong',
    title: 'Pong',
    screenSize: Size(screenWidth, screenHeight),
    scenes: {'gameplay': scene},
    startSceneId: 'gameplay',
