  final score2Display = Sprite(
    id: 'score2_display',
    position: Position(700, 50),
    size: Size(100, 60),
    backgroundColor: Color(r: 200, g: 0, b: 0),
  );

  // 센터 라인
  final centerLine = Sprite(
    id: 'center_line',
    position: Position(400, 300),
    size: Size(4, 600),
    backgroundColor: Color(r: 200, g: 200, b: 200),
  );

  final scene = Scene(
    id: 'gameplay',
    title: 'Pong',
    sprites: {
      'ball': ball,
      'paddle1': paddle1,
      'paddle2': paddle2,
      'score1_display': score1Display,
      'score2_display': score2Display,
      'center_line': centerLine,
    },
    backgroundColor: Color(r: 0, g: 0, b: 0), // 검정
    globalEvents: [
      // 공 벗어남 감지 (점수 증가)
      EventHandler(
        type: EventType.update,
        action: BallOutOfBoundsAction(
          ballId: 'ball',
          screenWidth: screenWidth,
        ),
      ),
      // 최대 점수 달성 감지 (게임 오버)
