// lsp_features.dart - LSP 기반 고급 기능
// 자동 완성, 린터, 코드 포맷팅

// ==================== 자동 완성 ====================

class CompletionItem {
  final String label;
  final String detail;
  final String documentation;
  final String insertText;
  final CompletionItemKind kind;

  CompletionItem({
    required this.label,
    required this.detail,
    required this.documentation,
    required this.insertText,
    required this.kind,
  });
}

enum CompletionItemKind {
  keyword,
  function,
  variable,
  type,
  module,
  snippet,
}

class AutocompleteProvider {
  static const List<String> keywords = [
    'let',
    'if',
    'else',
    'for',
    'while',
    'fn',
    'return',
    'break',
    'continue',
    'match',
    'true',
    'false',
    'nil',
  ];

  static const List<String> builtinFunctions = [
    'print',
    'println',
    'len',
    'push',
    'pop',
    'append',
    'slice',
    'contains',
    'indexOf',
    'toLowerCase',
    'toUpperCase',
    'trim',
    'split',
    'join',
  ];

  static const List<String> builtinTypes = [
    'i32',
    'i64',
    'f32',
    'f64',
    'string',
    'bool',
    'array',
    'object',
  ];

  /// 현재 커서 위치에서 자동 완성 제안 조회
  static List<CompletionItem> getCompletions(
    String code,
    int position,
  ) {
    final completions = <CompletionItem>[];

    // 커서 앞 텍스트 추출
    final beforeCursor = code.substring(0, position);
    final lastWord = _extractLastWord(beforeCursor);

    // 키워드 제안
    for (final keyword in keywords) {
      if (keyword.startsWith(lastWord)) {
        completions.add(CompletionItem(
          label: keyword,
          detail: 'Keyword',
          documentation: 'FreeLang keyword: $keyword',
          insertText: keyword,
          kind: CompletionItemKind.keyword,
        ));
      }
    }

    // 함수 제안
    for (final func in builtinFunctions) {
      if (func.startsWith(lastWord)) {
        completions.add(CompletionItem(
          label: func,
          detail: 'Function',
          documentation: 'Built-in function: $func()',
          insertText: '$func(\${1})',
          kind: CompletionItemKind.function,
        ));
      }
    }

    // 타입 제안
    for (final type in builtinTypes) {
      if (type.startsWith(lastWord)) {
        completions.add(CompletionItem(
          label: type,
          detail: 'Type',
          documentation: 'FreeLang type: $type',
          insertText: type,
          kind: CompletionItemKind.type,
        ));
      }
    }

    // 스니펫 제안
    final snippets = _getSnippets();
    for (final snippet in snippets) {
      if (snippet.label.startsWith(lastWord)) {
        completions.add(snippet);
      }
    }

    return completions;
  }

  static String _extractLastWord(String text) {
    final match = RegExp(r'\w*$').firstMatch(text);
    return match?.group(0) ?? '';
  }

  static List<CompletionItem> _getSnippets() {
    return [
      CompletionItem(
        label: 'fn',
        detail: 'Snippet',
        documentation: 'Function declaration',
        insertText: 'fn \${1:name}(\${2:params}) { \${3} }',
        kind: CompletionItemKind.snippet,
      ),
      CompletionItem(
        label: 'if',
        detail: 'Snippet',
        documentation: 'If statement',
        insertText: 'if (\${1:condition}) { \${2} }',
        kind: CompletionItemKind.snippet,
      ),
      CompletionItem(
        label: 'for',
        detail: 'Snippet',
        documentation: 'For loop',
        insertText: 'for (let i = 0; i < \${1:length}; i++) { \${2} }',
        kind: CompletionItemKind.snippet,
      ),
      CompletionItem(
        label: 'while',
        detail: 'Snippet',
        documentation: 'While loop',
        insertText: 'while (\${1:condition}) { \${2} }',
        kind: CompletionItemKind.snippet,
      ),
    ];
  }
}

// ==================== 린터 ====================

class Diagnostic {
  final int line;
  final int column;
  final String message;
  final DiagnosticSeverity severity;
  final String code;

  Diagnostic({
    required this.line,
    required this.column,
    required this.message,
    required this.severity,
    required this.code,
  });
}

enum DiagnosticSeverity {
  error,
  warning,
  information,
  hint,
}

class Linter {
  /// 코드 린팅 및 문제점 감지
  static List<Diagnostic> lint(String code) {
    final diagnostics = <Diagnostic>[];
    final lines = code.split('\n');

    for (int lineNum = 0; lineNum < lines.length; lineNum++) {
      final line = lines[lineNum];

      // 1. 구문 오류 감지
      final syntaxErrors = _checkSyntaxErrors(line, lineNum);
      diagnostics.addAll(syntaxErrors);

      // 2. 미사용 변수 감지
      final unusedVars = _checkUnusedVariables(code, lineNum);
      diagnostics.addAll(unusedVars);

      // 3. 타입 불일치 감지
      final typeErrors = _checkTypeErrors(line, lineNum);
      diagnostics.addAll(typeErrors);

      // 4. 스타일 경고 감지
      final styleWarnings = _checkStyleWarnings(line, lineNum);
      diagnostics.addAll(styleWarnings);
    }

    return diagnostics;
  }

  static List<Diagnostic> _checkSyntaxErrors(String line, int lineNum) {
    final diagnostics = <Diagnostic>[];

    // 괄호 짝맞음 확인
    int openParen = 0, openBrace = 0, openBracket = 0;
    for (int i = 0; i < line.length; i++) {
      final char = line[i];
      if (char == '(') openParen++;
      else if (char == ')') openParen--;
      else if (char == '{') openBrace++;
      else if (char == '}') openBrace--;
      else if (char == '[') openBracket++;
      else if (char == ']') openBracket--;

      if (openParen < 0 || openBrace < 0 || openBracket < 0) {
        diagnostics.add(Diagnostic(
          line: lineNum,
          column: i,
          message: 'Mismatched closing bracket',
          severity: DiagnosticSeverity.error,
          code: 'syntax-error',
        ));
        break;
      }
    }

    // 문장 끝 세미콜론 확인 (선택사항이지만 권장)
    if (line.trim().isNotEmpty &&
        !line.trim().endsWith('{') &&
        !line.trim().endsWith('}') &&
        !line.trim().endsWith(';')) {
      // 세미콜론 없음 경고 (힌트)
    }

    return diagnostics;
  }

  static List<Diagnostic> _checkUnusedVariables(String code, int lineNum) {
    final diagnostics = <Diagnostic>[];

    // 간단한 패턴 매칭: let x = ... 근데 x를 사용하지 않음
    final letPattern = RegExp(r'let\s+(\w+)\s*=');
    final lines = code.split('\n');

    for (int i = 0; i < lines.length; i++) {
      final match = letPattern.firstMatch(lines[i]);
      if (match != null) {
        final varName = match.group(1)!;
        // 이후 줄에서 varName이 사용되는지 확인
        bool isUsed = false;
        for (int j = i + 1; j < lines.length; j++) {
          if (lines[j].contains(varName)) {
            isUsed = true;
            break;
          }
        }

        if (!isUsed && i == lineNum) {
          diagnostics.add(Diagnostic(
            line: i,
            column: match.start,
            message: "Variable '$varName' is defined but never used",
            severity: DiagnosticSeverity.warning,
            code: 'unused-variable',
          ));
        }
      }
    }

    return diagnostics;
  }

  static List<Diagnostic> _checkTypeErrors(String line, int lineNum) {
    final diagnostics = <Diagnostic>[];

    // 간단한 타입 체크: string + number 같은 명백한 오류
    if (line.contains('+') && line.contains('"')) {
      // 더 정교한 타입 분석은 파서 필요
      // 여기서는 기본적인 패턴만 감지
    }

    return diagnostics;
  }

  static List<Diagnostic> _checkStyleWarnings(String line, int lineNum) {
    final diagnostics = <Diagnostic>[];

    // 들여쓰기 확인 (2칸 또는 4칸 권장)
    final leadingSpaces = line.length - line.trimLeft().length;
    if (leadingSpaces % 2 != 0 && leadingSpaces % 4 != 0 && leadingSpaces > 0) {
      diagnostics.add(Diagnostic(
        line: lineNum,
        column: 0,
        message: 'Incorrect indentation (use 2 or 4 spaces)',
        severity: DiagnosticSeverity.information,
        code: 'indentation',
      ));
    }

    // 사용하지 않은 import 감지
    if (line.contains('import') && !line.contains('use')) {
      // import 후 실제 사용 여부 확인
    }

    // 변수명 컨벤션 (camelCase 권장)
    final varPattern = RegExp(r'let\s+([a-z]+_[a-z]+)');
    final match = varPattern.firstMatch(line);
    if (match != null) {
      diagnostics.add(Diagnostic(
        line: lineNum,
        column: match.start,
        message: 'Variable name should use camelCase',
        severity: DiagnosticSeverity.hint,
        code: 'naming-convention',
      ));
    }

    return diagnostics;
  }
}

// ==================== 코드 포맷팅 ====================

class CodeFormatter {
  /// 코드를 표준 형식으로 포맷팅
  static String format(String code) {
    var formatted = code;

    // 1. 들여쓰기 정규화 (2칸)
    formatted = _normalizeIndentation(formatted);

    // 2. 공백 정리
    formatted = _cleanupWhitespace(formatted);

    // 3. 줄 길이 제한 (80자)
    formatted = _wrapLongLines(formatted, maxLength: 80);

    // 4. 연산자 주변 공백
    formatted = _formatOperators(formatted);

    return formatted;
  }

  static String _normalizeIndentation(String code) {
    final lines = code.split('\n');
    final formatted = <String>[];
    int indentLevel = 0;
    const indentStr = '  '; // 2칸

    for (final line in lines) {
      final trimmed = line.trim();
      if (trimmed.isEmpty) {
        formatted.add('');
        continue;
      }

      // 닫는 괄호는 들여쓰기 감소
      if (trimmed.startsWith('}') || trimmed.startsWith(']') || trimmed.startsWith(')')) {
        indentLevel = (indentLevel - 1).clamp(0, 100);
      }

      formatted.add('${'  ' * indentLevel}$trimmed');

      // 여는 괄호는 들여쓰기 증가
      if (trimmed.endsWith('{') || trimmed.endsWith('[') || trimmed.endsWith('(')) {
        indentLevel++;
      }
    }

    return formatted.join('\n');
  }

  static String _cleanupWhitespace(String code) {
    // 라인 끝 공백 제거
    var cleaned = code.split('\n').map((line) => line.trimRight()).join('\n');

    // 연속된 빈 줄을 최대 1개로
    cleaned = cleaned.replaceAll(RegExp(r'\n\n\n+'), '\n\n');

    // 파일 끝 개행 확인
    if (!cleaned.endsWith('\n')) {
      cleaned += '\n';
    }

    return cleaned;
  }

  static String _wrapLongLines(String code, {int maxLength = 80}) {
    final lines = code.split('\n');
    final wrapped = <String>[];

    for (final line in lines) {
      if (line.length <= maxLength) {
        wrapped.add(line);
      } else {
        // 길 줄 분할 (공백 기준)
        final parts = line.split(' ');
        var currentLine = '';
        for (final part in parts) {
          if ((currentLine + part).length > maxLength) {
            if (currentLine.isNotEmpty) {
              wrapped.add(currentLine);
              currentLine = '';
            }
            currentLine = part;
          } else {
            if (currentLine.isNotEmpty) {
              currentLine += ' ';
            }
            currentLine += part;
          }
        }
        if (currentLine.isNotEmpty) {
          wrapped.add(currentLine);
        }
      }
    }

    return wrapped.join('\n');
  }

  static String _formatOperators(String code) {
    var formatted = code;

    // 연산자 주변에 공백 추가
    formatted = formatted.replaceAll(RegExp(r'(\S)([+\-*/%=])(\S)'), r'$1 $2 $3');

    // 콤마 뒤에 공백
    formatted = formatted.replaceAll(RegExp(r',(\S)'), ', $1');

    return formatted;
  }
}

