// lsp_features_test.dart - LSP 기능 테스트

import 'package:flutter_test/flutter_test.dart';
import 'package:ide/services/lsp_features.dart';

void main() {
  group('AutocompleteProvider', () {
    test('자동 완성: 키워드 제안', () {
      const code = 'le';
      const position = 2;

      final completions = AutocompleteProvider.getCompletions(code, position);

      expect(completions.isNotEmpty, true);
      expect(
        completions.any((item) => item.label == 'let'),
        true,
      );
    });

    test('자동 완성: 함수 제안', () {
      const code = 'print';
      const position = 5;

      final completions = AutocompleteProvider.getCompletions(code, position);

      expect(
        completions.any((item) => item.label == 'print'),
        true,
      );
    });

    test('자동 완성: 타입 제안', () {
      const code = 'i3';
      const position = 2;

      final completions = AutocompleteProvider.getCompletions(code, position);

      expect(
        completions.any((item) => item.label == 'i32'),
        true,
      );
    });

    test('자동 완성: 스니펫 제안', () {
      const code = 'fn';
      const position = 2;

      final completions = AutocompleteProvider.getCompletions(code, position);

      expect(
        completions.any((item) => item.kind == CompletionItemKind.snippet),
        true,
      );
    });
  });

  group('Linter', () {
    test('린팅: 구문 오류 감지', () {
      const code = 'let x = (1 + 2))';

      final diagnostics = Linter.lint(code);

      expect(
        diagnostics.any((d) => d.code == 'syntax-error'),
        true,
      );
    });

    test('린팅: 미사용 변수 경고', () {
      const code = '''
let unused = 10
let used = 20
print used
''';

      final diagnostics = Linter.lint(code);

      expect(
        diagnostics.any((d) => d.code == 'unused-variable'),
        true,
      );
    });

    test('린팅: 들여쓰기 경고', () {
      const code = 'let x = 1\n   if x { print x }'; // 3칸 들여쓰기

      final diagnostics = Linter.lint(code);

      expect(
        diagnostics.any((d) => d.code == 'indentation'),
        true,
      );
    });

    test('린팅: 명명 컨벤션 경고', () {
      const code = 'let snake_case = 10';

      final diagnostics = Linter.lint(code);

      expect(
        diagnostics.any((d) => d.code == 'naming-convention'),
        true,
      );
    });

    test('린팅: 오류 없음', () {
      const code = '''
let x = 10
let y = 20
print x + y
''';

      final diagnostics = Linter.lint(code);

      // 오류 없음 (모두 경고/힌트만 가능)
      expect(
        diagnostics.where((d) => d.severity == DiagnosticSeverity.error).isEmpty,
        true,
      );
    });
  });

  group('CodeFormatter', () {
    test('포맷팅: 들여쓰기 정규화', () {
      const code = '''fn main() {
    let x = 1
        if x { print x }
}''';

      final formatted = CodeFormatter.format(code);

      expect(formatted.contains('  let'), true);
      expect(formatted.contains('    if'), true);
    });

    test('포맷팅: 공백 정리', () {
      const code = 'let x = 1  \nlet y = 2   ';

      final formatted = CodeFormatter.format(code);

      expect(!formatted.contains('  \n'), true);
    });

    test('포맷팅: 연산자 공백', () {
      const code = 'let x=1+2';

      final formatted = CodeFormatter.format(code);

      expect(formatted.contains(' = '), true);
      expect(formatted.contains(' + '), true);
    });

    test('포맷팅: 파일 끝 개행', () {
      const code = 'let x = 1';

      final formatted = CodeFormatter.format(code);

      expect(formatted.endsWith('\n'), true);
    });

    test('포맷팅: 완전한 코드', () {
      const code = '''fn fib(n) {
if n<=1 { n }
else { fib(n-1)+fib(n-2) }
}''';

      final formatted = CodeFormatter.format(code);

      // 정규화되어야 함
      expect(formatted.contains('  if'), true);
      expect(formatted.contains('  else'), true);
      expect(formatted.contains('fn fib'), true);
    });
  });
}

