   232→      case 'bool':
   233→        return bool_;
   234→      case 'nil':
   235→        return nil;
   236→      default:
   237→        return null;
   238→    }
   239→  }
   240→
   241→  /// 타입 이름 목록
   242→  static const List<String> allTypeNames = [
   243→    'i32',
   244→    'i64',
   245→    'f32',
   246→    'f64',
   247→    'string',
   248→    'bool',
   249→    'nil',
