import 'type_system.dart';
import 'lsp_features.dart' show Diagnostic, DiagnosticSeverity;

/// 패턴 추상 클래스
abstract class Pattern {
  /// 이 패턴이 주어진 값과 매치되는지 확인
  bool matches(String value);

  /// 패턴이 바인드하는 변수들의 타입
  Map<String, FreeLangType> bindings(TypeEnvironment env);
}

/// 리터럴 패턴: 42, "hello", true
class LiteralPattern extends Pattern {
  final String value;

  LiteralPattern(this.value);

  @override
  bool matches(String value) => this.value == value;

  @override
  Map<String, FreeLangType> bindings(TypeEnvironment env) => {};

  @override
  String toString() => value;
}

/// 와일드카드 패턴: _
class WildcardPattern extends Pattern {
  @override
  bool matches(String value) => true;

  @override
  Map<String, FreeLangType> bindings(TypeEnvironment env) => {};

  @override
  String toString() => '_';
}

/// 바인딩 패턴: x, n (변수에 값을 바인드)
class BindingPattern extends Pattern {
  final String name;
  final FreeLangType? expectedType; // 선택적 타입 주석

  BindingPattern(this.name, [this.expectedType]);

  @override
  bool matches(String value) => true;

  @override
  Map<String, FreeLangType> bindings(TypeEnvironment env) {
    return {name: expectedType ?? FreeLangTypes.unknown};
  }

  @override
  String toString() => name;
}

/// 튜플 패턴: (a, b), (x, y, z)
class TuplePattern extends Pattern {
  final List<Pattern> elements;

  TuplePattern(this.elements);

  @override
  bool matches(String value) => true; // 간단한 구현

  @override
  Map<String, FreeLangType> bindings(TypeEnvironment env) {
    final result = <String, FreeLangType>{};
    for (final elem in elements) {
      result.addAll(elem.bindings(env));
    }
    return result;
  }

  @override
  String toString() => '(${elements.join(', ')})';
}

/// 생성자 패턴: Some(x), Ok(value), Err(msg), None
class ConstructorPattern extends Pattern {
  final String name; // 'Some', 'Ok', 'Err', 'None'
  final List<Pattern> args;

  ConstructorPattern(this.name, [this.args = const []]);

  @override
  bool matches(String value) {
    return value.startsWith('$name(') || (value == name && args.isEmpty);
  }

  @override
  Map<String, FreeLangType> bindings(TypeEnvironment env) {
    final result = <String, FreeLangType>{};
    for (final arg in args) {
      result.addAll(arg.bindings(env));
    }
    return result;
  }

  @override
  String toString() => args.isEmpty ? name : '$name(${args.join(', ')})';
}

/// 가드 패턴: n if n > 0
class GuardPattern extends Pattern {
  final Pattern inner;
  final String guard; // 'n > 0', 'x != null'

  GuardPattern(this.inner, this.guard);

  @override
  bool matches(String value) => true; // 가드 조건 평가는 런타임에

  @override
  Map<String, FreeLangType> bindings(TypeEnvironment env) {
    return inner.bindings(env);
  }

  @override
  String toString() => '$inner if $guard';
}

/// 매치 암(arm) - 패턴 + 표현식
class MatchArm {
  final Pattern pattern;
  final String body;

  MatchArm(this.pattern, this.body);

  @override
  String toString() => '$pattern => $body';
}

/// 패턴 매칭 검사기
class PatternMatcher {
  /// 코드의 match 표현식 검사
  static List<Diagnostic> check(String code, TypeEnvironment env) {
    final diagnostics = <Diagnostic>[];
    final lines = code.split('\n');

    // match 표현식 찾기
    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      final match = RegExp(r'match\s+(\w+)\s*\{').firstMatch(line);
      if (match != null) {
        final varName = match.group(1)!;

        // 변수의 타입 조회
        final varType = env.lookup(varName);
        if (varType == null) {
          diagnostics.add(Diagnostic(
            line: i,
            column: match.start(1),
            message: "Unknown variable '$varName'",
            severity: DiagnosticSeverity.error,
            code: 'unknown-variable',
          ));
        }
      }
    }

    return diagnostics;
  }

  /// match 표현식이 완전한지 확인 (모든 경우 커버 여부)
  static bool isExhaustive(List<MatchArm> arms, FreeLangType type) {
