// module_system.dart - 모듈 시스템 (import/export, 네임스페이스)

import 'type_system.dart';
import 'lsp_features.dart' show Diagnostic, DiagnosticSeverity;

/// 모듈 선언 (module name { ... })
class ModuleDeclaration {
  final String name; // 'math', 'io', 'string'
  final List<String> exports; // 공개 심볼 목록
  final TypeEnvironment env; // 모듈 내부 환경

  ModuleDeclaration({
    required this.name,
    required this.exports,
    required this.env,
  });

  @override
  String toString() => 'module $name { exports: ${exports.join(", ")} }';

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ModuleDeclaration &&
          runtimeType == other.runtimeType &&
          name == other.name &&
          exports == other.exports;

  @override
  int get hashCode => Object.hash(name, exports);
}

/// import 선언
/// - import "math" as m
/// - import { add, sub } from "math"
/// - import * from "math"
class ImportDeclaration {
  final String modulePath; // "math", "std/io", "./utils"
  final String? alias; // m, io, utils (import ... as alias)
  final List<String>? symbols; // [add, sub] (import { add, sub } from)
  final bool isWildcard; // true (import * from)

  ImportDeclaration({
    required this.modulePath,
    this.alias,
    this.symbols,
    this.isWildcard = false,
  });

  @override
  String toString() {
    if (isWildcard) return 'import * from "$modulePath"';
    if (symbols != null && symbols!.isNotEmpty) {
      return 'import { ${symbols!.join(", ")} } from "$modulePath"';
    }
    if (alias != null) return 'import "$modulePath" as $alias';
    return 'import "$modulePath"';
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ImportDeclaration &&
          runtimeType == other.runtimeType &&
          modulePath == other.modulePath &&
          alias == other.alias &&
          symbols == other.symbols &&
          isWildcard == other.isWildcard;

  @override
  int get hashCode => Object.hash(modulePath, alias, symbols, isWildcard);
}

/// 모듈 레지스트리 - 모듈 등록 및 import 검증
class ModuleRegistry {
  final Map<String, ModuleDeclaration> _modules = {};

  /// 모듈 등록
