// async_system.dart - 비동기 시스템 (async/await, Future<T>)

import 'type_system.dart';
import 'lsp_features.dart' show Diagnostic, DiagnosticSeverity;

/// Future<T> 타입 - 비동기 연산 결과
class FutureType extends FreeLangType {
  final FreeLangType innerType;

  FutureType(this.innerType);

  @override
  String get name => 'Future<${innerType.name}>';

  @override
  bool isAssignableTo(FreeLangType other) {
    if (other is FutureType) {
      return innerType.isAssignableTo(other.innerType);
    }
    return false;
  }

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is FutureType &&
          runtimeType == other.runtimeType &&
          innerType == other.innerType;

  @override
  int get hashCode => Object.hash(innerType);
}

/// async 함수 타입
class AsyncFunctionType extends FunctionType {
  AsyncFunctionType({
    required List<FreeLangType> paramTypes,
    required FreeLangType returnType,
  }) : super(paramTypes: paramTypes, returnType: returnType);

  /// async fn의 실제 반환 타입은 Future<T>
  @override
  String get name {
    final paramStr = paramTypes.map((t) => t.name).join(', ');
    return 'async fn($paramStr) -> Future<${returnType.name}>';
  }

  /// async 함수의 innerType 추출
  FreeLangType get futureInnerType => returnType;
}

/// 비동기 검사기
class AsyncChecker {
  /// 코드의 비동기 관련 오류 검사
  static List<Diagnostic> check(
    String code,
    TypeEnvironment env,
  ) {
    final diagnostics = <Diagnostic>[];
    final lines = code.split('\n');

    // async 함수 선언 검사
    diagnostics.addAll(_checkAsyncFunctions(lines));

    // await 표현식 검사
    diagnostics.addAll(_checkAwaitExpressions(lines, env));

    return diagnostics;
  }

  /// async fn 선언 검사
  static List<Diagnostic> _checkAsyncFunctions(List<String> lines) {
    final diagnostics = <Diagnostic>[];

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      // async fn 선언 찾기
      final asyncMatch = RegExp(r'async\s+fn\s+(\w+)\s*\(').firstMatch(line);
      if (asyncMatch != null) {
        final fnName = asyncMatch.group(1)!;

        // async 함수는 Future<T>를 반환해야 함
        // 단순 문법 검사 (실제 반환 타입은 타입 체커가 확인)
        bool hasArrow = false;
        for (int j = i; j < lines.length && j < i + 5; j++) {
          if (lines[j].contains('->')) {
            hasArrow = true;
            break;
          }
        }

        // 화살표가 없으면 경고
        if (!hasArrow) {
          diagnostics.add(Diagnostic(
            line: i,
            column: asyncMatch.start(),
            message:
                "async function '$fnName' should have explicit return type annotation",
            severity: DiagnosticSeverity.warning,
            code: 'missing-return-type',
          ));
        }
      }
    }

    return diagnostics;
  }

  /// await 표현식 검사 (async 함수 내에서만 사용 가능)
  static List<Diagnostic> _checkAwaitExpressions(
    List<String> lines,
    TypeEnvironment env,
  ) {
    final diagnostics = <Diagnostic>[];

    // 현재 async 함수 범위 추적
    bool insideAsyncFn = false;
    int asyncFnStartLine = -1;

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      // async 함수 진입
      if (line.contains('async fn')) {
        insideAsyncFn = true;
        asyncFnStartLine = i;
      }

      // 함수 종료 감지 (간단한 휴리스틱)
      if (insideAsyncFn && line.trim() == '}' && i > asyncFnStartLine) {
        insideAsyncFn = false;
      }

      // await 표현식 찾기
      final awaitMatch = RegExp(r'await\s+(\w+)').firstMatch(line);
      if (awaitMatch != null) {
        final varName = awaitMatch.group(1)!;

        // await는 async 함수 내에서만 사용 가능
        if (!insideAsyncFn) {
          diagnostics.add(Diagnostic(
            line: i,
            column: awaitMatch.start(),
            message: "'await' can only be used inside async function",
            severity: DiagnosticSeverity.error,
            code: 'await-outside-async',
          ));
        }

        // 변수 타입 확인 (Future 타입이어야 함)
        final varType = env.lookup(varName);
        if (varType != null && varType is! FutureType) {
          diagnostics.add(Diagnostic(
            line: i,
            column: awaitMatch.start(1),
            message:
                "'await' can only be used with Future type, got ${varType.name}",
            severity: DiagnosticSeverity.error,
            code: 'future-type-required',
          ));
        }
      }
    }

    return diagnostics;
  }
}

/// 비동기 타입 추론
class AsyncInferrer {
  /// async 함수 선언 인식
  static bool isAsyncFunction(String fnDeclaration) {
    return fnDeclaration.contains('async fn');
  }

  /// await 표현식 타입 추론
  /// await Future<T> -> T
  static FreeLangType? inferAwait(FreeLangType futureType) {
    if (futureType is FutureType) {
      return futureType.innerType;
    }
    return null;
  }

  /// async 블록의 반환 타입 추론
  /// async { ... } -> Future<T>
  static FreeLangType inferAsync(
    String expr,
    TypeEnvironment env,
  ) {
    // 간단한 구현: 모든 async 표현식은 Future<unknown> 반환
    // 실제로는 블록 내 타입 추론 필요
    return FutureType(FreeLangTypes.unknown);
  }

  /// 함수 반환 타입 수정
  /// fn foo() -> i32 -> async fn foo() -> Future<i32>
  static FutureType wrapWithFuture(FreeLangType returnType) {
    return FutureType(returnType);
  }

  /// Future.resolve(value) 패턴 인식
  /// Future.resolve(42) -> Future<i32>
  static FreeLangType? inferFutureResolve(
    String expr,
    TypeEnvironment env,
  ) {
    final match = RegExp(r'Future\.resolve\(([^)]+)\)').firstMatch(expr);
    if (match != null) {
      // 간단히 unknown으로 처리
      // 실제로는 괄호 안 표현식 타입 추론
      return FutureType(FreeLangTypes.unknown);
    }
    return null;
  }

  /// 비동기 체인 타입 추론
  /// future1.then(|x| future2) -> Future<T>
  static FreeLangType? inferThen(
    String expr,
    TypeEnvironment env,
  ) {
    if (expr.contains('.then(')) {
      return FutureType(FreeLangTypes.unknown);
    }
    return null;
  }
}

