        for (int j = i; j < lines.length && j < i + 5; j++) {
          if (lines[j].contains('->')) {
            hasArrow = true;
            break;
          }
        }

        // 화살표가 없으면 경고
        if (!hasArrow) {
          diagnostics.add(Diagnostic(
            line: i,
            column: asyncMatch.start(),
            message:
                "async function '$fnName' should have explicit return type annotation",
            severity: DiagnosticSeverity.warning,
            code: 'missing-return-type',
          ));
        }
      }
    }

    return diagnostics;
  }

  /// await 표현식 검사 (async 함수 내에서만 사용 가능)
  static List<Diagnostic> _checkAwaitExpressions(
    List<String> lines,
    TypeEnvironment env,
  ) {
    final diagnostics = <Diagnostic>[];

    // 현재 async 함수 범위 추적
    bool insideAsyncFn = false;
    int asyncFnStartLine = -1;

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      // async 함수 진입
      if (line.contains('async fn')) {
        insideAsyncFn = true;
        asyncFnStartLine = i;
      }

      // 함수 종료 감지 (간단한 휴리스틱)
      if (insideAsyncFn && line.trim() == '}' && i > asyncFnStartLine) {
        insideAsyncFn = false;
      }

      // await 표현식 찾기
      final awaitMatch = RegExp(r'await\s+(\w+)').firstMatch(line);
      if (awaitMatch != null) {
        final varName = awaitMatch.group(1)!;

        // await는 async 함수 내에서만 사용 가능
        if (!insideAsyncFn) {
          diagnostics.add(Diagnostic(
            line: i,
            column: awaitMatch.start(),
            message: "'await' can only be used inside async function",
            severity: DiagnosticSeverity.error,
            code: 'await-outside-async',
          ));
        }

        // 변수 타입 확인 (Future 타입이어야 함)
        final varType = env.lookup(varName);
        if (varType != null && varType is! FutureType) {
          diagnostics.add(Diagnostic(
            line: i,
            column: awaitMatch.start(1),
            message:
                "'await' can only be used with Future type, got ${varType.name}",
            severity: DiagnosticSeverity.error,
            code: 'future-type-required',
          ));
        }
      }
    }

    return diagnostics;
  }
}

/// 비동기 타입 추론
class AsyncInferrer {
  /// async 함수 선언 인식
  static bool isAsyncFunction(String fnDeclaration) {
    return fnDeclaration.contains('async fn');
  }

  /// await 표현식 타입 추론
  /// await Future<T> -> T
  static FreeLangType? inferAwait(FreeLangType futureType) {
    if (futureType is FutureType) {
      return futureType.innerType;
    }
    return null;
  }

  /// async 블록의 반환 타입 추론
  /// async { ... } -> Future<T>
  static FreeLangType inferAsync(
    String expr,
    TypeEnvironment env,
  ) {
    // 간단한 구현: 모든 async 표현식은 Future<unknown> 반환
    // 실제로는 블록 내 타입 추론 필요
    return FutureType(FreeLangTypes.unknown);
  }

  /// 함수 반환 타입 수정
  /// fn foo() -> i32 -> async fn foo() -> Future<i32>
  static FutureType wrapWithFuture(FreeLangType returnType) {
    return FutureType(returnType);
  }

  /// Future.resolve(value) 패턴 인식
  /// Future.resolve(42) -> Future<i32>
  static FreeLangType? inferFutureResolve(
    String expr,
    TypeEnvironment env,
  ) {
    final match = RegExp(r'Future\.resolve\(([^)]+)\)').firstMatch(expr);
    if (match != null) {
      // 간단히 unknown으로 처리
      // 실제로는 괄호 안 표현식 타입 추론
      return FutureType(FreeLangTypes.unknown);
    }
    return null;
  }

  /// 비동기 체인 타입 추론
  /// future1.then(|x| future2) -> Future<T>
  static FreeLangType? inferThen(
    String expr,
    TypeEnvironment env,
  ) {
    if (expr.contains('.then(')) {
      return FutureType(FreeLangTypes.unknown);
    }
    return null;
  }
}

