// unified_analyzer.dart - 통합 분석기 (모든 Phase 검사기 파이프라인)

import 'type_system.dart';
import 'type_checker.dart';
import 'type_inference.dart';
import 'generics_system.dart';
import 'trait_system.dart';
import 'error_handling.dart';
import 'pattern_matcher.dart';
import 'module_system.dart';
import 'async_system.dart';
import 'lsp_features.dart' show Diagnostic, DiagnosticSeverity;

/// 타입 힌트
class TypeHint {
  final int line;
  final int column;
  final String type;
  final String? documentation;

  TypeHint({
    required this.line,
    required this.column,
    required this.type,
    this.documentation,
  });

  @override
  String toString() => 'TypeHint($line:$column: $type)';
}

/// 분석 결과
class AnalysisResult {
  final List<Diagnostic> diagnostics;
  final List<TypeHint> typeHints;
  final List<String> importedModules;
  final bool hasAsyncCode;
  final TypeEnvironment environment;

  AnalysisResult({
    required this.diagnostics,
    required this.typeHints,
    required this.importedModules,
    required this.hasAsyncCode,
    required this.environment,
  });

  /// 에러 개수
  int get errorCount =>
      diagnostics.where((d) => d.severity == DiagnosticSeverity.error).length;

  /// 경고 개수
  int get warningCount =>
      diagnostics.where((d) => d.severity == DiagnosticSeverity.warning).length;

  /// 정보 개수
  int get informationCount => diagnostics
      .where((d) => d.severity == DiagnosticSeverity.information)
      .length;

  /// 전체 진단 개수
  int get totalCount => diagnostics.length;

  @override
  String toString() =>
      'AnalysisResult($errorCount errors, $warningCount warnings, $informationCount info, ${typeHints.length} hints)';
}

/// 통합 분석기 - 모든 검사기를 파이프라인으로 연결
class UnifiedAnalyzer {
  final ModuleRegistry moduleRegistry;
  final TraitRegistry traitRegistry;

  UnifiedAnalyzer({
    ModuleRegistry? moduleRegistry,
    TraitRegistry? traitRegistry,
  })  : moduleRegistry = moduleRegistry ?? ModuleRegistry.withStdlib(),
        traitRegistry = traitRegistry ?? TraitRegistry.withBuiltins();

  /// 전체 분석 파이프라인
  /// 입력 코드를 모든 검사기를 거쳐 분석
  AnalysisResult analyze(String code) {
    final diagnostics = <Diagnostic>[];
    final typeHints = <TypeHint>[];
    final importedModules = <String>[];
    final env = TypeEnvironment();

    // ========== Step 1: 모듈 가져오기 검사 ==========
    final moduleImports = ModuleParser.parseImports(code);
    for (final import in moduleImports) {
      importedModules.add(import.modulePath);
    }

    // 모듈 존재 여부 확인
    final moduleDiagnostics = ModuleParser.checkImports(code, moduleRegistry);
    diagnostics.addAll(moduleDiagnostics);

    // ========== Step 2: 기본 타입 검사 ==========
    final typeDiagnostics = TypeChecker.check(code, env);
    diagnostics.addAll(typeDiagnostics);

    // ========== Step 3: 타입 추론 (힌트 수집) ==========
    final hints = _collectTypeHints(code, env);
    typeHints.addAll(hints);

    // ========== Step 4: 제네릭 검사 ==========
    final genericDiagnostics = GenericsParser.checkGenericUsage(code);
    diagnostics.addAll(genericDiagnostics);

    // ========== Step 5: 트레이트 검사 ==========
    final traitDiagnostics = TraitChecker.check(code, traitRegistry);
    diagnostics.addAll(traitDiagnostics);

    // ========== Step 6: 에러 핸들링 검사 ==========
    final errorDiagnostics = ErrorHandlingChecker.check(code, env);
    diagnostics.addAll(errorDiagnostics);

    // ========== Step 7: 패턴 매칭 검사 ==========
    final patternDiagnostics = PatternMatcher.check(code, env);
    diagnostics.addAll(patternDiagnostics);

    // ========== Step 8: 비동기 검사 ==========
    final hasAsyncCode = code.contains('async fn') || code.contains('await ');
    final asyncDiagnostics = AsyncChecker.check(code, env);
    diagnostics.addAll(asyncDiagnostics);

    // ========== Step 9: 최종 검증 ==========
    // 중복 진단 제거 (같은 위치, 같은 메시지)
    final uniqueDiagnostics = _deduplicateDiagnostics(diagnostics);

    // 심각도로 정렬 (에러 > 경고 > 정보)
    uniqueDiagnostics.sort((a, b) {
      final severityOrder = {
        DiagnosticSeverity.error: 0,
        DiagnosticSeverity.warning: 1,
        DiagnosticSeverity.information: 2,
      };
      final aOrder = severityOrder[a.severity] ?? 3;
      final bOrder = severityOrder[b.severity] ?? 3;
      if (aOrder != bOrder) return aOrder.compareTo(bOrder);
      return a.line.compareTo(b.line);
    });

    return AnalysisResult(
      diagnostics: uniqueDiagnostics,
      typeHints: typeHints,
      importedModules: importedModules,
      hasAsyncCode: hasAsyncCode,
      environment: env,
    );
  }

  /// 타입 힌트 수집
  List<TypeHint> _collectTypeHints(String code, TypeEnvironment env) {
    final hints = <TypeHint>[];
    final lines = code.split('\n');

    for (int i = 0; i < lines.length; i++) {
      final line = lines[i];

      // let x: Type = value 패턴
      final letMatch = RegExp(r'let\s+(\w+)\s*:\s*(\w+)').firstMatch(line);
      if (letMatch != null) {
        hints.add(TypeHint(
          line: i,
          column: letMatch.start(1),
          type: letMatch.group(2)!,
          documentation: 'Variable declaration with explicit type',
        ));
      }

      // fn name(params) -> Type 패턴
      final fnMatch = RegExp(r'fn\s+(\w+)\s*\([^)]*\)\s*->\s*(\w+)')
          .firstMatch(line);
      if (fnMatch != null) {
        hints.add(TypeHint(
          line: i,
          column: fnMatch.start(2),
          type: fnMatch.group(2)!,
          documentation: 'Function return type',
        ));
      }
    }

    return hints;
  }

  /// 중복 진단 제거
  List<Diagnostic> _deduplicateDiagnostics(List<Diagnostic> diagnostics) {
    final seen = <String, bool>{};
    final unique = <Diagnostic>[];

    for (final diag in diagnostics) {
      final key = '${diag.line}:${diag.column}:${diag.message}';
      if (seen[key] != true) {
        seen[key] = true;
        unique.add(diag);
      }
    }

    return unique;
  }
}

/// 분석 캐시 (성능 최적화)
class AnalysisCache {
  final Map<String, AnalysisResult> _cache = {};
  final Map<String, int> _hashes = {};

  /// 코드 변경 여부 확인
  bool hasChanged(String code) {
    final hash = code.hashCode;
    if (_hashes['last'] == hash) {
      return false;
    }
    _hashes['last'] = hash;
    return true;
  }

  /// 캐시된 결과 가져오기
  AnalysisResult? get(String code) {
    if (!hasChanged(code)) {
      return _cache['last'];
    }
    return null;
  }

  /// 결과 캐시
  void cache(String code, AnalysisResult result) {
    _cache['last'] = result;
  }

  /// 캐시 초기화
  void clear() {
    _cache.clear();
    _hashes.clear();
  }
}

/// 분석 통계
class AnalysisStats {
  int totalAnalyses = 0;
  int totalErrors = 0;
  int totalWarnings = 0;
  DateTime? lastAnalysisTime;

  /// 분석 결과 통합
  void recordAnalysis(AnalysisResult result) {
    totalAnalyses++;
    totalErrors += result.errorCount;
    totalWarnings += result.warningCount;
    lastAnalysisTime = DateTime.now();
  }

  /// 통계 초기화
  void reset() {
    totalAnalyses = 0;
    totalErrors = 0;
    totalWarnings = 0;
    lastAnalysisTime = null;
  }

  @override
  String toString() =>
      'AnalysisStats(analyses: $totalAnalyses, errors: $totalErrors, warnings: $totalWarnings)';
}

