void _performTypeCheck(String code) {
  try {
    // 통합 분석기 사용
    final analyzer = UnifiedAnalyzer();
    final result = analyzer.analyze(code);

    // 진단 결과 로깅
    if (result.diagnostics.isNotEmpty) {
      print('[UnifiedAnalyzer] ${result.errorCount}개 에러, ${result.warningCount}개 경고 발견');
      for (final diag in result.diagnostics) {
        print('[${diag.severity}] ${diag.message} (line ${diag.line}, code: ${diag.code})');
      }
    }

    // 타입 힌트 로그
    if (result.typeHints.isNotEmpty) {
      print('[TypeHints] ${result.typeHints.length}개 타입 힌트:');
      for (final hint in result.typeHints) {
        print('[TypeHint] $hint');
      }
    }

    // 가져온 모듈 로그
    if (result.importedModules.isNotEmpty) {
      print('[Modules] ${result.importedModules.length}개 모듈 가져옴: ${result.importedModules.join(", ")}');
    }

    // 비동기 코드 감지
    if (result.hasAsyncCode) {
      print('[Async] 비동기 코드 감지됨');
    }
  } catch (e) {
    print('[UnifiedAnalyzer Error] $e');
  }
}

