// module_async_test.dart - Phase 10 모듈 & 비동기 테스트 (27개)

import 'package:flutter_test/flutter_test.dart';
import 'package:ide/services/type_system.dart';
import 'package:ide/services/module_system.dart';
import 'package:ide/services/async_system.dart';
import 'package:ide/services/unified_analyzer.dart';
import 'package:ide/services/trait_system.dart';
import 'package:ide/services/pattern_matcher.dart';
import 'package:ide/services/lsp_features.dart' show DiagnosticSeverity;

void main() {
  group('모듈 시스템 (Module System)', () {
    test('Test 1: ImportDeclaration 파싱 - 단순 import', () {
      const code = 'import "math"';
      final imports = ModuleParser.parseImports(code);
      expect(imports.length, 1);
      expect(imports[0].modulePath, 'math');
      expect(imports[0].alias, isNull);
      expect(imports[0].symbols, isNull);
      expect(imports[0].isWildcard, false);
    });

    test('Test 2: ImportDeclaration 파싱 - as alias', () {
      const code = 'import "math" as m';
      final imports = ModuleParser.parseImports(code);
      expect(imports.length, 1);
      expect(imports[0].modulePath, 'math');
      expect(imports[0].alias, 'm');
    });

    test('Test 3: ImportDeclaration 파싱 - 중괄호 import', () {
      const code = 'import { add, sub, mul } from "math"';
      final imports = ModuleParser.parseImports(code);
      expect(imports.length, 1);
      expect(imports[0].modulePath, 'math');
      expect(imports[0].symbols, ['add', 'sub', 'mul']);
    });

    test('Test 4: ImportDeclaration 파싱 - 와일드카드', () {
      const code = 'import * from "io"';
      final imports = ModuleParser.parseImports(code);
      expect(imports.length, 1);
      expect(imports[0].isWildcard, true);
      expect(imports[0].modulePath, 'io');
    });

    test('Test 5: ModuleDeclaration 파싱', () {
      const code = 'module math { export add, sub, mul }';
      final module = ModuleParser.parseModule(code);
      expect(module, isNotNull);
      expect(module!.name, 'math');
      expect(module.exports, contains('add'));
      expect(module.exports, contains('sub'));
      expect(module.exports, contains('mul'));
    });

    test('Test 6: ModuleRegistry 등록 및 조회', () {
      final registry = ModuleRegistry();
      final mathModule = ModuleDeclaration(
        name: 'math',
        exports: ['add', 'sub'],
        env: TypeEnvironment(),
      );
      registry.registerModule(mathModule);
      expect(registry.resolve('math'), isNotNull);
      expect(registry.resolve('math')!.name, 'math');
    });

    test('Test 7: 내장 stdlib 모듈', () {
      final registry = ModuleRegistry.withStdlib();
      expect(registry.resolve('io'), isNotNull);
      expect(registry.resolve('math'), isNotNull);
      expect(registry.resolve('string'), isNotNull);
    });

    test('Test 8: import 검사 - 올바른 모듈', () {
      const code = 'import "math" as m';
      final registry = ModuleRegistry.withStdlib();
      final diagnostics = ModuleParser.checkImports(code, registry);
      expect(
        diagnostics.where((d) => d.code == 'module-not-found').isEmpty,
        true,
      );
    });

    test('Test 9: import 검사 - 없는 모듈 오류', () {
      const code = 'import "unknown_module"';
      final registry = ModuleRegistry.withStdlib();
      final diagnostics = ModuleParser.checkImports(code, registry);
      expect(
        diagnostics.any((d) => d.code == 'module-not-found'),
        true,
      );
    });

    test('Test 10: 모듈 심볼 내보내기 확인', () {
      final registry = ModuleRegistry.withStdlib();
      expect(registry.isExported('math', 'add'), true);
      expect(registry.isExported('math', 'PI'), true);
      expect(registry.isExported('math', 'unknown_fn'), false);
    });
  });

  group('비동기 시스템 (Async System)', () {
    test('Test 11: FutureType 생성', () {
      final future = FutureType(FreeLangTypes.i32);
      expect(future.name, 'Future<i32>');
    });

    test('Test 12: FutureType 호환성', () {
      final future1 = FutureType(FreeLangTypes.i32);
      final future2 = FutureType(FreeLangTypes.i32);
      expect(future1.isAssignableTo(future2), true);
    });

    test('Test 13: async 함수 선언 인식', () {
      const code = 'async fn fetchData() -> Future<string> { "data" }';
      expect(AsyncInferrer.isAsyncFunction(code), true);
    });

    test('Test 14: await 표현식 타입 추론', () {
      final futureInt = FutureType(FreeLangTypes.i32);
      final result = AsyncInferrer.inferAwait(futureInt);
      expect(result, FreeLangTypes.i32);
    });

    test('Test 15: await Future<i32> -> i32', () {
      final future = FutureType(FreeLangTypes.i32);
      final unwrapped = AsyncInferrer.inferAwait(future);
      expect(unwrapped!.name, 'i32');
    });

    test('Test 16: await 올바른 사용 (async 내)', () {
      const code = '''async fn test() -> Future<i32> {
  let result = Future.resolve(42)
  await result
}''';
      final env = TypeEnvironment();
      final diagnostics = AsyncChecker.check(code, env);
      expect(
        diagnostics.where((d) => d.code == 'await-outside-async').isEmpty,
        true,
      );
    });

    test('Test 17: await 오류 (async 밖)', () {
      const code = '''fn test() -> i32 {
  let result = Future.resolve(42)
  await result
}''';
      final env = TypeEnvironment();
      final diagnostics = AsyncChecker.check(code, env);
      expect(
        diagnostics.any((d) => d.code == 'await-outside-async'),
        true,
      );
    });

    test('Test 18: async fn 반환 타입 추론', () {
      final future = AsyncInferrer.inferAsync(
        'async { 42 }',
        TypeEnvironment(),
      );
      expect(future is FutureType, true);
    });

    test('Test 19: Future.resolve() 패턴', () {
      const code = 'let x = Future.resolve(10)';
      final type = AsyncInferrer.inferFutureResolve(code, TypeEnvironment());
      expect(type is FutureType, true);
    });

    test('Test 20: 비동기 + 에러 처리 통합', () {
      const code = '''async fn safeFetch() -> Future<Result<string, string>> {
  try {
    let data = Future.resolve("ok")
    Ok(await data)
  } catch(e: string) {
    Err(e)
  }
}''';
      final analyzer = UnifiedAnalyzer();
      final result = analyzer.analyze(code);
      expect(result.hasAsyncCode, true);
    });
  });

  group('통합 분석기 (Unified Analyzer)', () {
    test('Test 21: UnifiedAnalyzer 기본 분석', () {
      const code = '''let x: i32 = 10
print x''';
      final analyzer = UnifiedAnalyzer();
      final result = analyzer.analyze(code);
      expect(result.totalCount >= 0, true);
    });

    test('Test 22: 타입 + 트레이트 통합', () {
      const code = '''impl Printable for MyType {
  fn toString() -> string { "MyType" }
}''';
      final analyzer = UnifiedAnalyzer();
      final result = analyzer.analyze(code);
      // 트레이트 체크와 타입 체크 모두 실행
      expect(result.totalCount >= 0, true);
    });

    test('Test 23: 에러 + 패턴 통합', () {
      const code = '''let result: Result<i32, string> = Ok(42)
match result {
  Ok(x) => x,
  Err(e) => 0
}''';
      final analyzer = UnifiedAnalyzer();
      final result = analyzer.analyze(code);
      expect(result.diagnostics, isNotNull);
    });

    test('Test 24: 비동기 + 타입 통합', () {
      const code = '''async fn fetchUser() -> Future<i32> {
  let id: i32 = 1
  Future.resolve(id)
}''';
      final analyzer = UnifiedAnalyzer();
      final result = analyzer.analyze(code);
      expect(result.hasAsyncCode, true);
    });

    test('Test 25: 모듈 + 타입 통합', () {
      const code = '''import { add, sub } from "math"
let result: i32 = add(1, 2)''';
      final analyzer = UnifiedAnalyzer();
      final result = analyzer.analyze(code);
      expect(result.importedModules, contains('math'));
    });

    test('Test 26: 완전한 코드 0 오류', () {
      const code = '''import "math" as m
let x: i32 = 10
print x''';
      final analyzer = UnifiedAnalyzer();
      final result = analyzer.analyze(code);
      // 유효한 코드는 에러 없음
      expect(
        result.diagnostics
            .where((d) => d.severity == DiagnosticSeverity.error)
            .isEmpty,
        true,
      );
    });

    test('Test 27: 복합 오류 감지', () {
      const code = '''import "unknown"
let x: i32 = "string"
async fn test() {
  await x
}''';
      final analyzer = UnifiedAnalyzer();
      final result = analyzer.analyze(code);
      // 여러 에러 감지: 모듈 없음, 타입 불일치, await 오류
      expect(result.errorCount > 0, true);
    });
  });

  group('AnalysisResult 유틸리티', () {
    test('AnalysisResult 에러/경고 카운트', () {
      const code = '''import "unknown"
let x: i32 = 10''';
      final analyzer = UnifiedAnalyzer();
      final result = analyzer.analyze(code);
      expect(result.errorCount >= 0, true);
      expect(result.warningCount >= 0, true);
    });

    test('TypeHint 생성', () {
      const code = 'let x: i32 = 10';
      final analyzer = UnifiedAnalyzer();
      final result = analyzer.analyze(code);
      expect(result.typeHints, isNotNull);
    });
  });
}

